WHERE ap_schedules.is_active = 1

      AND ap_schedules.branch_id == #{filter.branchId}


  AND ap_schedules.start_date >= #{filter.dateFrom}


  AND ap_schedules.start_date <= #{filter.dateTo}


  AND (purchase_orders.po_code LIKE CONCAT('%', #{filter.searchText}, '%'))

mapper.select:
SELECT



ORDER BY


    ${filter.orderBy}


    ap_schedules.id ASC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM chart_accounts
WHERE is_active < 2 AND account_codes = #{accountCode}
 AND id != #{id}

mapper.update:
UPDATE ap_schedules SET
  is_active = 2,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id};

mapper.select:
SELECT CASE WHEN po_type = 1 THEN 'Product' ELSE 'Fix Asset' END AS name, COUNT(purchase_orders.vendor_id) AS total, IFNULL(SUM(purchase_orders.balance), 0) AS totalBalance FROM purchase_orders WHERE purchase_orders.status > 0 AND purchase_orders.balance > 0 AND purchase_orders.id IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1 AND ap_schedule_details.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
AND ap_schedules.start_date <= NOW() ) GROUP BY po_type

SELECT CASE WHEN po_type = 1 THEN 'Product' ELSE 'Fix Asset' END AS name, COUNT(purchase_orders.vendor_id) AS total, SUM(purchase_orders.balance) As totalBalance FROM purchase_orders WHERE purchase_orders.status >= 1 AND purchase_orders.balance > 0 AND purchase_orders.id IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1 AND ap_schedule_details.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
) GROUP BY po_type

SELECT (SELECT CONCAT(last_name, ' ',first_name) FROM users WHERE id = ap_schedules.created_by) AS name, COUNT(purchase_orders.vendor_id) AS total, IFNULL(SUM(purchase_orders.balance), 0) As totalBalance FROM purchase_orders INNER JOIN ap_schedule_details ON purchase_orders.id = ap_schedule_details.purchase_order_id AND ap_schedule_details.is_active = 1 INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE purchase_orders.status > 0 AND purchase_orders.balance > 0 AND ap_schedules.is_active = 1 AND purchase_orders.id IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id AND ap_schedule_details.is_active = 1 WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
) GROUP BY po_type

SELECT purchase_orders.vendor_id, IFNULL(SUM(purchase_orders.balance), 0) As totalAmountPBBookedByWeek FROM purchase_orders WHERE purchase_orders.status > 0 AND purchase_orders.balance > 0 AND purchase_orders.id IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
AND ap_schedules.start_date BETWEEN DATE_SUB(CURDATE(), INTERVAL DAYOFWEEK(CURDATE()) - 2 DAY) AND DATE_ADD(DATE_SUB(CURDATE(), INTERVAL DAYOFWEEK(CURDATE()) - 2 DAY), INTERVAL 6 DAY) ) GROUP BY purchase_orders.vendor_id ORDER BY purchase_orders.id ASC

SELECT purchase_orders.vendor_id AS vendorId, (SELECT name FROM vendors WHERE id = purchase_orders.vendor_id) As vendorName, IFNULL(SUM(purchase_orders.balance), 0) As totalBalanceTD FROM purchase_orders WHERE purchase_orders.status >= 1 AND purchase_orders.balance > 0 AND purchase_orders.id NOT IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
) GROUP BY purchase_orders.vendor_id ORDER BY totalBalanceTD DESC

SELECT vendors.id As vendorId, vendors.photo AS vendorPhoto, vendors.work_telephone AS vendorWorkTelephone, vendors.email_address AS vendorEmail, vendors.address AS vendorAddress, vendors.vendor_code AS vendorCode, vendors.name AS vendorName, SUM(purchase_orders.balance) As totalBalanceTD FROM purchase_orders INNER JOIN vendors ON vendors.id = purchase_orders.vendor_id WHERE purchase_orders.status >= 1 AND purchase_orders.balance > 0 AND purchase_orders.id NOT IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1 AND ap_schedule_details.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
) GROUP BY purchase_orders.vendor_id ORDER BY totalBalanceTD DESC LIMIT 3

SELECT purchase_orders.id AS purchaseOrderId, purchase_orders.order_date AS orderDate, TIMESTAMPDIFF(DAY, purchase_orders.order_date, NOW()) AS daysDifference, purchase_orders.po_code AS purchaseOrderCode FROM purchase_orders INNER JOIN vendors ON vendors.id = purchase_orders.vendor_id WHERE purchase_orders.vendor_id = #{filter.vendorId} AND purchase_orders.status > 0 AND purchase_orders.balance > 0 AND purchase_orders.id NOT IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
AND ap_schedules.start_date >= DATE(#{filter.dateFrom}) AND ap_schedules.start_date <= DATE(#{filter.dateTo})
) ORDER BY vendors.id,purchase_orders.order_date DESC LIMIT 10

SELECT purchase_orders.vendor_id, (SELECT name FROM vendors WHERE id = purchase_orders.vendor_id) AS vendorName, SUM(purchase_orders.balance) AS totalBalanceTD FROM purchase_orders WHERE purchase_orders.status >= 1 AND purchase_orders.balance > 0 AND purchase_orders.id IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
) GROUP BY purchase_orders.vendor_id ORDER BY totalBalanceTD DESC

SELECT vendors.id As vendorId, vendors.photo AS vendorPhoto, vendors.work_telephone AS vendorWorkTelephone, vendors.email_address AS vendorEmail, vendors.address AS vendorAddress, vendors.vendor_code AS vendorCode, vendors.name AS vendorName, SUM(purchase_orders.balance) AS totalBalanceTD FROM purchase_orders INNER JOIN vendors ON vendors.id = purchase_orders.vendor_id WHERE purchase_orders.status >= 1 AND purchase_orders.balance > 0 AND purchase_orders.id IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
) GROUP BY purchase_orders.vendor_id ORDER BY totalBalanceTD DESC LIMIT 3

SELECT purchase_orders.id AS purchaseOrderId, purchase_orders.order_date AS orderDate, ap_schedules.start_date AS date, purchase_orders.po_code AS purchaseOrderCode, SUM(purchase_orders.balance) AS totalBalanceTD FROM purchase_orders INNER JOIN vendors ON vendors.id = purchase_orders.vendor_id INNER JOIN ap_schedule_details ON purchase_orders.id = ap_schedule_details.purchase_order_id AND ap_schedule_details.is_active = 1 INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE purchase_orders.vendor_id = #{filter.vendorId} AND purchase_orders.status >= 1 AND purchase_orders.balance > 0 AND ap_schedules.is_active = 1 AND purchase_orders.id IN ( SELECT purchase_order_id FROM ap_schedule_details INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE ap_schedules.is_close = 0 AND ap_schedules.is_active = 1 AND ap_schedule_details.is_active = 1
AND ap_schedules.branch_id = #{filter.branchId}
) ORDER BY vendors.id, purchase_orders.order_date DESC

SELECT CONCAT('Week ', CEIL(DAY(ap_schedules.start_date) / 7) ) AS name, COUNT(purchase_orders.vendor_id) AS total, IFNULL(SUM(purchase_orders.balance), 0) AS totalBalance FROM purchase_orders INNER JOIN ap_schedule_details ON purchase_orders.id = ap_schedule_details.purchase_order_id AND ap_schedule_details.is_active = 1 INNER JOIN ap_schedules ON ap_schedules.id = ap_schedule_details.ap_schedule_id WHERE purchase_orders.status > 0 AND purchase_orders.balance > 0 AND ap_schedules.is_active = 1 AND ap_schedules.is_close = 0
AND ap_schedules.branch_id = #{filter.branchId}
AND MONTH(ap_schedules.start_date) = MONTH(NOW()) AND YEAR(ap_schedules.start_date) = YEAR(NOW()) GROUP BY CEIL(DAY(ap_schedules.start_date) / 7) ORDER BY CEIL(DAY(ap_schedules.start_date) / 7);
